def need(ok,message):
    if not ok: raise AssertionError(message)
def close(a,b):
    try: return np.shape(a)==np.shape(b) and np.allclose(np.asarray(a,dtype=float),np.asarray(b,dtype=float),rtol=1e-6,atol=1e-7)
    except (TypeError,ValueError): return False
def line(ax,x,y):
    matches=[l for l in ax.lines if close(l.get_xdata(),x) and close(l.get_ydata(),y)]
    need(bool(matches),'Plot the required x/y data as a line.'); return matches[0]
def scatter(ax,x,y):
    matches=[c for c in ax.collections if isinstance(c,PathCollection) and close(c.get_offsets(),np.column_stack([x,y]))]
    need(bool(matches),'Use scatter() with the required x/y data.'); return matches[0]
def color(artist,value): need(close(to_rgba(artist.get_color()),to_rgba(value)),'Use the requested line color: '+value)
def includes_vertices(collection,x,y):
    vertices=collection.get_paths()[0].vertices
    keys={tuple(v) for v in np.round(vertices,6)}
    return all(tuple(v) in keys for v in np.round(np.column_stack([x,np.broadcast_to(y,np.shape(x))]),6))
def grid(ax): need(any(l.get_visible() for l in ax.get_xgridlines()) and any(l.get_visible() for l in ax.get_ygridlines()),'Show a grid on both axes.')
def labels(ax,title=None,x=None,y=None):
    if title is not None: need(ax.get_title()==title,'Set the title to '+title)
    if x is not None: need(ax.get_xlabel()==x,'Set the x-axis label to '+x)
    if y is not None: need(ax.get_ylabel()==y,'Set the y-axis label to '+y)
def legend(ax,values):
    leg=ax.get_legend();need(leg is not None,'Display the legend with legend().')
    need([t.get_text() for t in leg.get_texts()]==values,'Use the requested legend labels and order.')
